scripts.吴来.txt:
//和吴来对话

	If ($Suba == 210) @Sub210;
	If ($Suba == 220) @Sub220;
	
	Say("赌棍：噫，真他娘的倒霉。");
	Say("庄家：行了，你小子都发了这么大笔财，还在乎这点。快下注，快下注！");
	Say("赌棍：他娘的，赌了！");
	Return;
	
@Sub210:
	Say("庄家：嘿——我说吴来，你他妈真无赖，刚赢了就想开溜。");
	Say("吴来：老子都输了几十两了，今儿手背，改天了。");
	Say("庄家：嗨，慢着，上次你欠八老板的五十两银子，该还了吧！");
	Say("吴来：什，什么五十两，不就十两吗？");
	Say("庄家：是吗，看来兄弟们得给你提个醒了！");
	Say("吴来：你们——");
	Say("独孤剑：你就是吴来？", 1);
	Say("吴来：大侠！对，对，我就是。我早就等着你了，走走，外头谈。");
	Say("庄家：（嘀咕）臭小子。");
	Say("独孤剑：是你就好！我问你，云笑风托你办的事呢？", 5);
	Say("吴来：云，云……我从来就不认识什么云风啊的，大侠搞错了吧。");
	Say("独孤剑：你从他那拿走两百两银子，还说不认识！", 5);
	Say("庄家：噢，我说你小子今儿个怎么突然发了大财了，原来这样！");
	Say("吴来：这，这个……八，八老板呢，我还他钱，我这就还……");
	Say("庄家：臭小子，这会来这套。八老板现在不在，这帐，咱们慢慢算。");
	Say("独孤剑：你还抵赖。像你这种无赖，应该一剑了结了你！", 5);
	Say("吴来：大——侠——大侠饶命啊！小的见财起意，小的无耻下流，杀了我，只会脏了大侠的剑……");
	Say("独孤剑：那你快帮云大哥去找他的朋友！否则，休怪我——", 5);
	Say("吴来：大侠，你不如杀了我吧！他朋友早见了阎王爷了……不，早死了，让我上哪找去？");
	Say("独孤剑：怎么回事！", 6);
	Say("吴来：半年前，小的还在船坞做事时，的确有个叫草草的北方人来过。后来他上了一条去湖南的商船，两月前听说那条船在洞庭湖被水盗劫了，船上二百来口全喂了水鬼了。那个草草只怕也早死了！");
	Say("独孤剑：啊——", 6);
	Say("吴来：大侠，这是一百两银子，就只剩这么多了。求大侠放小的走吧！");
	Say("独孤剑：……滚！", 5);
	Say("吴来：多谢大侠！多谢大侠！");
	Say("追回一百两银子。");
	NpcGoto("吴来",10,41);
	SetNpcPos("吴来",0,0);
	Say("独孤剑：想不到……", 1);
	AddMoney(100);
	Assign($Suba, 220);
	Return;
	
@Sub220:
	Say("吴来：大，大侠，小的只是……玩玩还不行吗？");
	Return;

